INSERT INTO about_me_entry_image (about_me_entry_id, image_id) VALUES
((SELECT ame.about_me_entry_id FROM about_me_entry ame JOIN about_me_group amg ON ame.about_me_group_id = amg.about_me_group_id JOIN language l ON ame.language_id = l.language_id WHERE amg.slug = 'about-me' AND l.code = 'EN' AND ame.part = 1), (SELECT image_id FROM about_me_image WHERE image_url = 'https://images.pexels.com/photos/31159549/pexels-photo-31159549.jpeg')),
((SELECT ame.about_me_entry_id FROM about_me_entry ame JOIN about_me_group amg ON ame.about_me_group_id = amg.about_me_group_id JOIN language l ON ame.language_id = l.language_id WHERE amg.slug = 'about-me' AND l.code = 'EN' AND ame.part = 2), (SELECT image_id FROM about_me_image WHERE image_url = 'https://images.pexels.com/photos/7148374/pexels-photo-7148374.jpeg')),
((SELECT ame.about_me_entry_id FROM about_me_entry ame JOIN about_me_group amg ON ame.about_me_group_id = amg.about_me_group_id JOIN language l ON ame.language_id = l.language_id WHERE amg.slug = 'about-me' AND l.code = 'NL' AND ame.part = 1), (SELECT image_id FROM about_me_image WHERE image_url = 'https://images.pexels.com/photos/31159549/pexels-photo-31159549.jpeg')),
((SELECT ame.about_me_entry_id FROM about_me_entry ame JOIN about_me_group amg ON ame.about_me_group_id = amg.about_me_group_id JOIN language l ON ame.language_id = l.language_id WHERE amg.slug = 'about-me' AND l.code = 'NL' AND ame.part = 2), (SELECT image_id FROM about_me_image WHERE image_url = 'https://images.pexels.com/photos/7148374/pexels-photo-7148374.jpeg'));